def solve():
    S = list(range(1, 192))
    sum_S = sum(S)

    # Candidate: R = all even numbers
    R_even = [x for x in S if x % 2 == 0]
    if len(R_even) >= 95:
        sum_R_even = sum(R_even)
        remaining_sum_even = sum_S - sum_R_even
        print(f"Even: sum_R={sum_R_even}, remaining={remaining_sum_even}, len={len(R_even)}")
    else:
        print("Even: Too small")

    # Candidate: R = {k, k+1, ..., 191}
    for k in range(1, 192):
        R_k = list(range(k, 192))
        if len(R_k) >= 95:
            # Check Rule (i)
            rule1 = True
            for x in R_k:
                if 2*x in S and 2*x not in R_k:
                    rule1 = False
                    break
            if not rule1:
                continue
            # Check Rule (ii)
            rule2 = True
            for i in range(len(R_k)):
                for j in range(i, len(R_k)):
                    if R_k[i] + R_k[j] in S and R_k[i] + R_k[j] not in R_k:
                        rule2 = False
                        break
                if not rule2:
                    break
            if rule2:
                print(f"R_k={k}: sum_R={sum(R_k)}, remaining={sum_S-sum(R_k)}, len={len(R_k)}")

solve()
